539:  // advance sprint→done 的结构前提（见 statemachine：done 前至少要有一条，不论 verdict——
540-  // reject 的证据同样算「评审过」，是否要打回重来归 precheck/审计裁，这道闸只问「评审过没有」）。
541-  // 落点与 sprint-rework 一致：追加进同一份 sprints/<id>.json 的 reviews[]（append-item）。
542-  'review-evidence': {
543-    path: (id) => `sprints/${id}.json`,
544-    mode: 'append-item',
545-    validate(data, id) {
546-      mustObject(data, '评审证据');
547-      mustNonEmptyString(data.sprint, 'sprint（证据针对哪个 sprint）');
548-      if (data.sprint !== id) {
549-        throw new Error(`评审证据的 --id「${id}」与 data.sprint「${data.sprint}」不一致，写错档案了`);
550-      }
551-      mustNonEmptyString(data.who, 'who（评审人）');
552:      if (data.verdict !== 'pass' && data.verdict !== 'reject') {
553:        throw new Error('verdict（评审结论）只能是 pass（通过）或 reject（打回）');
554-      }
555-      mustNonEmptyString(data.tried, 'tried（试图证伪时做了什么，如起服务/跑测试/边界穿刺）');
556-      mustNonEmptyString(data.evidence, 'evidence（关键观察，允许引用文件路径）');
557-      mustInteger(data.at_tick, 'at_tick（发生在第几轮）');
558-    }
559-  }
560-};
561-
562-// 汇报八栏定义：渲染器按这个顺序出栏目，缺一栏就报错、不出残缺汇报。
563-// source 是数据源标识，渲染器按它去取数——数字栏全由脚本填，AI 的嘴不许碰账。
564-// 汇报只留三栏「人读要点」：本轮工作内容 / 主要产出 / 下轮计划——全取自 tick 草稿的结构化字段，
565-// 逐条 bullet。花费/进度/质量/待拍板/异常这些不进汇报了，改在 UI 的账单/里程碑树/审批区/异常角标看
566-// （数字栏本就现算自账本与档案，UI 已各有其位，塞进汇报只会把「这轮干了啥」糊成天书）。
